    [Fact]
    public async Task Admin_ListsEligibleServices_CreatesProduct_AndRejectsOtherRoles()
    {
        await EnableSubscription();using var admin=Client();using var customer=Client();using var provider=Client();await Login(admin,factory.Credentials[RoleCodes.Admin]);await Login(customer,factory.Credentials[RoleCodes.Customer]);await Login(provider,factory.Credentials[RoleCodes.Provider]);
        var services=await admin.GetFromJsonAsync<List<SubscriptionServiceItem>>("/api/v1/admin/subscriptions/eligible-services");Assert.Contains(services!,x=>x.Id==factory.Catalog.ServiceId);
        var response=await admin.PostAsJsonAsync("/api/v1/admin/subscriptions/products",new{serviceCategoryId=factory.Catalog.ServiceId,productName="월간 생활 점검",description="정기 방문 점검 상품",serviceScopeText="월 1회 기본 생활 점검",visitsPerPeriod=1,expectedDurationMinutes=60,billingPeriodCode="MONTHLY",standardMonthlyAmount=(decimal?)null,standardVisitAmount=(decimal?)null,effectiveFrom=DateOnly.FromDateTime(DateTime.Today),effectiveTo=(DateOnly?)null,isActive=true});
        Assert.Equal(HttpStatusCode.OK,response.StatusCode);var product=await response.Content.ReadFromJsonAsync<CareProductResponse>();Assert.Equal("월간 생활 점검",product!.ProductName);Assert.Null(product.StandardMonthlyAmount);
        Assert.Equal(HttpStatusCode.Forbidden,(await customer.GetAsync("/api/v1/admin/subscriptions/products")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await provider.GetAsync("/api/v1/admin/subscriptions/products")).StatusCode);
    }

    [Fact]
    public async Task Request_SupportsStandardAndCustom_WithStructuredRecurrence_AndHidesPrivacy()
    {
        await EnableSubscription();using var admin=Client();using var customer=Client();using var provider=Client();await Login(admin,factory.Credentials[RoleCodes.Admin]);await Login(customer,factory.Credentials[RoleCodes.Customer]);await Login(provider,factory.Credentials[RoleCodes.Provider]);var product=await CreateProduct(admin);
        var standard=await CreateRequest(customer,"STANDARD",product.Id);var custom=await CreateRequest(customer,"CUSTOM",null,"서울시 상세주소 101동 202호");Assert.Equal("WEEKLY",standard.Recurrence.FrequencyTypeCode);Assert.Equal(2,standard.Recurrence.Weekdays.Count);Assert.Null(custom.CareProductId);
        var application=await Apply(provider,custom.Id,"privacy");Assert.NotNull(application);var body=await (await customer.GetAsync($"/api/v1/subscriptions/requests/{custom.Id}/applications")).Content.ReadAsStringAsync();Assert.DoesNotContain("상세주소",body);Assert.DoesNotContain("\"phone\"",body,StringComparison.OrdinalIgnoreCase);
