    [Fact]
    public async Task ProviderApplication_ValidatesApprovalServiceArea_Requirements_AndDuplicate()
    {
        await ResetNegativeProviders();
        await EnableSubscription();using var customer=Client();using var provider=Client();using var inactive=Client();using var mismatch=Client();using var area=Client();await Login(customer,factory.Credentials[RoleCodes.Customer]);await Login(provider,factory.Credentials[RoleCodes.Provider]);await Login(inactive,factory.InactiveProviderCredential);await Login(mismatch,factory.ServiceMismatchProviderCredential);await Login(area,factory.AreaMismatchProviderCredential);var request=await CreateRequest(customer,"CUSTOM",null);
        Assert.Equal(HttpStatusCode.OK,(await ApplyRaw(provider,request.Id,"valid")).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await ApplyRaw(provider,request.Id,"duplicate")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await ApplyRaw(inactive,request.Id,"inactive")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await ApplyRaw(mismatch,request.Id,"service")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await ApplyRaw(area,request.Id,"area")).StatusCode);
